SELECT COALESCE(SUM(amount), 0)
FROM TRANSACTIONS
WHERE user_id = #{userId}
  AND type = 'EXPENSE'
  AND category <> 'CARD_WITHDRAWAL'
  AND transaction_date BETWEEN #{condition.startDate} AND #{condition.endDate}

SELECT COALESCE(SUM(amount), 0)
FROM TRANSACTIONS
WHERE user_id = #{userId}
  AND type = 'INCOME'
  AND transaction_date BETWEEN #{condition.startDate} AND #{condition.endDate}

SELECT transaction_id AS transactionId, transaction_date AS date, type AS type, CASE WHEN category = 'OTHER' THEN 'ETC' ELSE category END AS category, amount AS amount, merchant_name AS merchantName FROM TRANSACTIONS WHERE user_id = #{userId} AND transaction_date BETWEEN #{condition.startDate} AND #{condition.endDate} AND category <> 'CARD_WITHDRAWAL'
AND category IN ('OTHER', 'ETC')
AND type = 'TRANSFER' AND category = #{condition.category}
AND category = #{condition.category}
ORDER BY transaction_date DESC, transaction_time DESC, transaction_id DESC LIMIT #{condition.size} OFFSET #{condition.offset}

